import {t,initSettings,preferences} from './i18n.js';
import {eventsFor,lifeMood} from './events.js';
import {symbolPaths,symbolMarkup} from './event-graphics.js';
import {AXES,balanced,newLife,begin,transfer,live,replay,validate,sanitiseProfile,goals} from './sim.js';
import {drawWorld} from './world.js';
import {routineCaption} from './routines.js';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';let state=newLife(),age=0,speed=2,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,mode='world',tab='priorities',travel=null,elapsed=0,lastTime=0,lastPaint=0,dirty=true,saveOK=true,lastCheckpoint=0;
try{const raw=localStorage.getItem('life-course-v2');if(raw){const s=JSON.parse(raw);if(validate(s)){state=s;age=s.stage==='birth'?(s.progressAge??s.age):s.age;}}}catch{saveOK=false;}
const money=v=>'฿'+v.toLocaleString('en');function svgEl(tag,attrs={},text){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;return el;}
function save(){try{localStorage.setItem('life-course-v2',JSON.stringify({...state,progressAge:state.stage==='birth'?age:state.age}));}catch{saveOK=false;}$('save-status').textContent='Fictional life · '+(saveOK?'saved in this browser':'browser save unavailable');}
function radar(){const el=$('radar');el.replaceChildren();const point=(i,v)=>{const a=-Math.PI/2+i*2*Math.PI/5;return[150+Math.cos(a)*75*v/10,112+Math.sin(a)*75*v/10]};const poly=v=>AXES.map((a,i)=>point(i,typeof v==='number'?v:v[a.key]).join(',')).join(' ');for(const ring of [2,5,10])el.append(svgEl('polygon',{points:poly(ring),fill:'none',stroke:'#b4b9a9','stroke-width':.7}));AXES.forEach((a,i)=>{const q=point(i,10);el.append(svgEl('line',{x1:150,y1:112,x2:q[0],y2:q[1],stroke:'#b4b9a9','stroke-width':.7}));const t=point(i,13);el.append(svgEl('text',{x:t[0],y:t[1]+4,'text-anchor':'middle'},a.key==='iq'?'IQ':a.key==='eq'?'EQ':a.label));});if(state.original)el.append(svgEl('polygon',{points:poly(state.original),fill:'none',stroke:'#52635b','stroke-width':1,'stroke-dasharray':'3 3'}));el.append(svgEl('polygon',{points:poly(state.effort),fill:'#f59e0b','fill-opacity':.25,stroke:'#a35d00','stroke-width':2}));el.setAttribute('aria-label','Ten-point allocation: '+AXES.map(a=>a.label+' '+state.effort[a.key]).join(', '));}
function allocations(){const root=$('allocation');root.replaceChildren();for(const a of AXES){const row=document.createElement('div');row.className='allocation-row';const label=document.createElement('span');label.textContent=a.key==='iq'?'IQ':a.key==='eq'?'EQ':a.label;const output=document.createElement('output');output.textContent=state.effort[a.key];const minus=document.createElement('button'),plus=document.createElement('button');for(const[b,d,t]of [[minus,-1,'−'],[plus,1,'+']]){b.type='button';b.dataset.point=a.key+':'+d;b.textContent=t;b.setAttribute('aria-label',(d>0?'Add one point to ':'Remove one point from ')+a.label);b.disabled=d>0?state.effort[a.key]===10:state.effort[a.key]===0;b.onclick=()=>{const point=b.dataset.point;state={...state,effort:transfer(state.effort,a.key,d)};render();document.querySelector(`[data-point="${point}"]`)?.focus({preventScroll:true});};}row.append(label,minus,output,plus);root.append(row);}radar();}
function field(key,label,options){const wrap=document.createElement('div');wrap.className='profile-field';const l=document.createElement('label');l.textContent=label;l.htmlFor='profile-'+key;const select=document.createElement('select');select.id='profile-'+key;select.name=key;for(const[value,text]of options){const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o);}select.value=state.profile[key];select.onchange=()=>{state={...state,profile:sanitiseProfile({...state.profile,[key]:select.value},state.age)};render();document.querySelector(`[name="${key}"]`)?.focus({preventScroll:true});};wrap.append(l,select);$('profile').append(wrap);}
function profiles(){const root=$('profile');root.replaceChildren();field('aim','What would make these five years worthwhile?',Object.entries(goals));field('religion','Religion or spiritual practice · expressive choice',[['explore','Still exploring'],['practice','Make time for practice'],['none','No religious practice']]);if(state.age>=20){field('drink','Alcohol in your social life',[['no','I can socialise without drinking'],['social','I would drink socially']]);field('smoke','Smoking',[['no','I would not smoke'],['yes','I would smoke']]);field('intimacy','Love and sex · expressive choice',[['unsure','I am still figuring it out'],['together','I want them together'],['separate','They can be separate']]);}else{const p=document.createElement('p');p.className='profile-note';p.textContent='Adult habits and relationship values open after 15, at your age-20 review. Your choices can change later.';root.append(p);}}
function chart(id,key,max,min=0){const el=$(id);el.setAttribute('role','group');el.replaceChildren();const rows=state.history.length?state.history:[{age:0,health:state.health,wellbeing:state.wellbeing,cash:state.cash}];const x=a=>32+a/80*298,y=v=>76-(v-min)/(max-min)*60;for(const v of [min,max])el.append(svgEl('text',{x:0,y:y(v)+4},key==='cash'?(Math.abs(v)>=1000?Math.round(v/1000)+'k':String(Math.round(v))):String(v)));for(const a of [0,20,40,60,80]){el.append(svgEl('text',{x:x(a),y:106,'text-anchor':'middle'},String(a)));}el.append(svgEl('line',{x1:32,y1:76,x2:330,y2:76,stroke:'#b4b9a9'}));if(min<0)el.append(svgEl('line',{x1:32,y1:y(0),x2:330,y2:y(0),stroke:'#9a9e90','stroke-dasharray':'3 3'}));el.append(svgEl('polyline',{points:rows.map(r=>[x(r.age),y(r[key])].join(',')).join(' '),fill:'none',stroke:'#192e2c','stroke-width':2}));for(const r of rows)el.append(svgEl('circle',{cx:x(r.age),cy:y(r[key]),r:2,fill:'#a35d00'}));for(const r of rows){eventsFor(r).filter(e=>e.category===key).forEach((event,index)=>{const marker=svgEl('g',{transform:`translate(${x(r.age)},${Math.max(8,y(r[key])-10-index*14)})`,tabindex:0,role:'button','aria-label':t('Age {n}'.replace('{n}',r.age))+': '+t(event.label)});marker.append(svgEl('path',{d:symbolPaths[event.symbol],fill:'var(--paper)',stroke:'#192e2c','stroke-width':1.5}));marker.append(svgEl('title',{},t(event.label)));const show=()=>{$('event-detail').textContent='Age '+r.age+': '+event.label+' — '+r.event;};marker.onclick=show;marker.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}};el.append(marker);});}el.setAttribute('aria-label',key+' by age: '+rows.map(r=>r.age+': '+Math.round(r[key])).join(', '));}
function eventLedger(){const root=$('event-list');root.replaceChildren();for(const row of state.history)for(const event of eventsFor(row)){const li=document.createElement('li'),b=document.createElement('button');b.type='button';b.innerHTML=symbolMarkup(event.symbol);const label=document.createElement('span');label.textContent=row.age+' · '+t(event.label);b.append(label);b.onclick=()=>{$('event-detail').textContent='Age '+row.age+': '+event.label+' — '+row.event;};li.append(b);root.append(li);}if(!root.children.length)$('event-detail').textContent='No major event recorded.';const mood=lifeMood(state);$('mood-note').textContent=t(mood==='bright'?'Bright period':mood==='difficult'?'Difficult period':'Steady period')+' · '+t('World colours follow recent changes; the recorded values do not change.');}
function charts(){eventLedger();$('health-value').textContent=Math.round(state.health)+' / 100';$('wellbeing-value').textContent=Math.round(state.wellbeing)+' / 100';$('cash-value').textContent=money(state.cash);chart('health-chart','health',100);chart('wellbeing-chart','wellbeing',100);const values=[0,state.cash,...state.history.map(r=>r.cash)];chart('cash-chart','cash',Math.max(10000,...values)*1.12,Math.min(0,...values)*1.12);}
function recap(){const root=$('recap');root.replaceChildren();const text=document.createElement('p');text.className='recap-title';text.textContent=state.death?'The rest was never promised.':'Eighty years. No straight line.';root.append(text);const list=document.createElement('ol');for(const r of state.history.filter(r=>r.age>=15)){const li=document.createElement('li');const strongest=AXES.reduce((a,b)=>r.effort[a.key]>=r.effort[b.key]?a:b);li.textContent=`${r.from}–${r.age}: ${goals[r.profile.aim]}. Most effort: ${strongest.label} (${r.effort[strongest.key]}/10). ${r.event} ${r.profile.smoke==='yes'?'Smoking was part of your routine. ':''}${r.profile.drink==='social'?'You drank socially. ':''}${r.profile.religion==='practice'?'You made space for spiritual practice. ':''}${r.profile.intimacy==='together'?'You wanted love and sex together.':r.profile.intimacy==='separate'?'You saw love and sex as separable.':''}`;list.append(li);}root.append(list);if(state.previous){const p=document.createElement('p');p.className='previous';p.textContent=`Your previous life in this scenario reached ${state.previous.age}, with ${money(state.previous.cash)} remaining. Comparing different lengths of life does not measure success.`;root.prepend(p);}}
function render(){const birth=state.stage==='birth';document.body.classList.toggle('birth-stage',birth);const end=state.stage==='recap',moving=!!travel,review=state.stage==='review'&&!moving;const first=state.profiles.length===0;$('editor').hidden=!review;$('recap').hidden=!end;$('birth-info').hidden=!birth;$('commit').hidden=birth||moving;$('overview').hidden=birth;$('title').textContent=birth?'Before you choose.':moving?'Life keeps moving.':end?(state.death?'Your life ends at '+state.age+'.':'The life you made.'):first?'Your starting attributes':'Your next five years';$('chapter').textContent=birth?'THE BEGINNING':end?'YOUR LIFE, REPLAYED':moving?'BETWEEN THE STATIONS':'FIVE-YEAR REVIEW';$('stage-count').textContent=birth?'0 → 10':end?'0 → '+state.age:state.age+' → '+Math.min(80,state.age+5);$('narrative').textContent=birth?`Born into ${state.birth.home} in ${state.birth.place}. For the first ten years, watch your world grow. The first choices come at 10.`:moving?'Time carries your choices forward. The world keeps going around you.':end?(state.death?.cause??'Your choices made a shape. Some plans held; others changed. Follow the amber course to see where you went.'):first?'Ten points. Choose a starting shape; revise your priorities every five years.':`Set your effort for ages ${state.age}–${Math.min(80,state.age+5)}.`;
if(birth){$('birth-info').replaceChildren();const dl=document.createElement('dl');for(const[label,value]of [['Your household',state.birth.home],['Starting condition',state.birth.body],['Temperament',state.birth.sensitivity]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}$('birth-info').append(dl);}if(review){allocations();profiles();$('priorities').hidden=tab!=='priorities';$('profile').hidden=tab!=='profile';$('tab-priorities').setAttribute('aria-pressed',String(tab==='priorities'));$('tab-profile').setAttribute('aria-pressed',String(tab==='profile'));$('effect-preview').hidden=tab==='priorities';$('points-note').textContent='10 / 10 points';document.querySelector('.allocation-heading strong').textContent=first?'Your starting attributes':'Effort for these five years';$('shape-comparison').querySelector('summary').textContent=first?'View your starting shape':'Compare with your starting shape';document.querySelector('.starting-key').hidden=first;$('effect-preview').textContent=tab==='profile'?'Goals affect this model’s wellbeing. Expressive choices are recorded in your life story.':(state.age>=20&&state.profile.smoke==='yes'?'Smoking costs money and physical health in this model.':'Priorities change your skills, resources and wellbeing.');}if(end)recap();$('commit').textContent=end?'Live another path →':first?'Begin your path →':'Live 5 years →';const last=state.history.at(-1);$('last-event').textContent=last&&state.age>10&&!moving?last.event:'';$('age-track').replaceChildren();for(let i=0;i<=16;i++){const el=document.createElement('span');el.className=i*5<=age?'past':'';$('age-track').append(el);}charts();save();dirty=true;}
function setAge(){const n=Math.floor(age);document.querySelectorAll('#age-track span').forEach((el,i)=>el.classList.toggle('past',i*5<=age));$('age-track').setAttribute('aria-valuenow',String(n));$('age').textContent='Age '+n;$('location').textContent=n<3?'Your family home':n<6?'Beyond the cradle':n<10?'Your neighborhood':state.birth.place;$('scene-caption').textContent=mode==='course'?'Your original priorities and the departures you made.':state.stage==='recap'?'A metaphorical world. A very particular life.':routineCaption(age,elapsed,state.profiles.at(-1)?.profile.aim??'balance');$('world').setAttribute('aria-label',mode==='course'?'Life course from birth to '+state.age+', with planned age stations and recorded changes in priorities.':`Age ${n}: ${n<3?'a close view of the family around a baby in a cradle':n<10?'the view expands to home, neighbors and school':'the family home, school, market, clinic, sports field and workplaces share a metaphorical neighborhood'}.`);}
$('commit').onclick=()=>{if(state.stage==='recap'){state=replay(state);age=0;mode='world';paused=false;tab='priorities';render();return;}if(state.stage!=='review'||travel)return;let source=state;if(state.profiles.length===0){source={...state,attributes:{...state.effort},original:{...state.effort},history:state.history.map(r=>({...r,effort:{...state.effort}}))};}travel={from:age,to:live(source)};mode='world';paused=false;render();};$('tab-priorities').onclick=()=>{tab='priorities';render()};$('tab-profile').onclick=()=>{tab='profile';render()};$('overview').onclick=()=>{mode=mode==='world'?'course':'world';$('overview').textContent=mode==='world'?'Life course':'Growing world';setAge();dirty=true;};$('reset').onclick=()=>{state=newLife(state.seed+1);age=0;travel=null;tab='priorities';mode='world';paused=false;render();};$('soundless').onclick=()=>{paused=!paused;dirty=true;};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(q=>q.setAttribute('aria-pressed',String(q===b)));});
function tick(now){const dt=lastTime?Math.min((now-lastTime)/1000,.1):0;lastTime=now;const automatic=state.stage==='birth'||!!travel;const motionAllowed=!preferences.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;const animating=!paused&&motionAllowed;if(animating){elapsed+=dt*speed;if(automatic){age+=dt*speed/4;if(state.stage==='birth'&&age>=10){state=begin(state);age=10;render();}else if(travel&&age>=travel.to.age){state=travel.to;travel=null;age=state.age;if(state.stage==='recap')mode='course';render();}}}else if(!paused&&automatic&&!motionAllowed){age=state.stage==='birth'?10:travel.to.age;if(state.stage==='birth')state=begin(state);else{state=travel.to;travel=null;}if(state.stage==='recap')mode='course';render();}if(dirty||(animating&&now-lastPaint>=(automatic?50:125))){lastPaint=now;setAge();drawWorld($('world'),state,age,elapsed,mode);$('soundless').textContent=paused?'Resume':'Pause';$('soundless').setAttribute('aria-pressed',String(paused));dirty=false;}if(state.stage==='birth'&&now-lastCheckpoint>2000){lastCheckpoint=now;save();}requestAnimationFrame(tick);}window.addEventListener('life-preferences',()=>{dirty=true;charts();});initSettings();window.addEventListener('resize',()=>{dirty=true;});document.addEventListener('visibilitychange',()=>{lastTime=0;});render();requestAnimationFrame(tick);
